// Helper to fill placeholders in a string
function fillPlaceholders(text, data) {
    let res = text;
    // Handle Conditionals {{#key}}...{{/key}}
    const sectionRegex = /{{#(\w+)}}([\s\S]*?){{\/\1}}/g;
    res = res.replace(sectionRegex, (match, key, content) => {
        return (data[key] && String(data[key]).trim() !== '') ? content : '';
    });
    // Handle Standard Variables {{key}}
    for (const key in data) {
        res = res.replace(new RegExp(`{{${key}}}`, 'g'), data[key] ?? '');
    }
    return res;
}

let finalMessage = "";

if (items.length === 0) {
    finalMessage = "No history found.";
} else {
    // Check if this is a "Compressed" template
    const parts = template.split('[REPEATING_ROW]');

    if (parts.length === 3) {
        // COMPRESSED LOGIC (Header + Loop + Footer)
        const header = fillPlaceholders(parts[0], items[0].json);
        const rowTemplate = parts[1];
        const footer = fillPlaceholders(parts[2], items[0].json);

        const rows = items.map(item => fillPlaceholders(rowTemplate, item.json)).join('\n');
        finalMessage = `${header}\n${rows}\n${footer}`;
    } else {
        // ORIGINAL LOGIC (Repeat the whole template for each item)
        finalMessage = items.map(item => fillPlaceholders(template, item.json)).join('\n\n---\n\n');
    }
}

return {
