const timePart = new Date().toLocaleTimeString('en-GB', { hour12: false }).replace(/:/g, '').slice(0, 4); 
const reference = `POS-${datePart}-${timePart}`;

return [
  {
    json: {
      date: date,
      description: description,
      reference: reference,
      lines: [
        {
          account_id: cash_account_id,
          debit: amount,
          credit: 0
        },
        {
          account_id: sales_account_id,
          debit: 0,
          credit: amount
        }
      ]
    }
  }
];

