// This code assumes:
// 1. $input.item.json is the AI's updated JSON object
// 2. You have a way to reference the "original" state (e.g., from an 'Edit Fields' node)

const aiOutput = $input.first().json;
const originalState = $('Execute a SQL query').first().json.selections

/**
 * Deep merges two objects. 
 * If the source (AI) has a non-null value, it overwrites the target.
 */
function mergeSelections(target, source) {
  if (typeof source !== 'object' || source === null) {
    return target;
  }

  Object.keys(source).forEach(key => {
    const sourceValue = source[key];
    const targetValue = target[key];

    if (Array.isArray(sourceValue) && Array.isArray(targetValue)) {
      // For arrays (like layer_definitions), merge by index
      sourceValue.forEach((item, index) => {
        if (targetValue[index]) {
          targetValue[index] = mergeSelections(targetValue[index], item);
        } else {
          targetValue.push(item);
        }
      });
    } else if (typeof sourceValue === 'object' && sourceValue !== null) {
      // Recurse for nested objects
      target[key] = mergeSelections(targetValue || {}, sourceValue);
    } else {
      // Only update if the AI provided a non-null value
      if (sourceValue !== null && sourceValue !== undefined) {
        target[key] = sourceValue;
      }
    }
  });

  return target;
}

const mergedResult = mergeSelections(JSON.parse(JSON.stringify(originalState)), aiOutput);

return {
  user_selections: mergedResult
};

// 1. Data Retrieval
const old_selection = $('Execute a SQL query').first().json.selections || {};
const new_ai_extraction = $('HTTP Request').first().json || {}; 
const config = $('Edit Fields').first().json.order_config;

// Initialize results
let validated_state = JSON.parse(JSON.stringify(old_selection));
let error_items = {};
let missing_items = {};

// --- Helper: Dynamic Rank/Value Resolver ---
function getOptionData(fieldKey, value) {
    if (value === null || value === undefined || value === "") return { value: null, rank: -1 };

    const settings = config[fieldKey];
    const valStr = value.toString().toLowerCase();

    // Extract numbers (e.g., "10 inch" -> 10)
    const numericValue = parseFloat(valStr.replace(/[^\d.]/g, '')); 

    if (isNaN(numericValue)) {
        const index = settings?.options ? settings.options.findIndex(opt => opt.toLowerCase() === valStr) : -1;
        return { value: value, rank: index !== -1 ? (index + 100) : -1 };
    }

    return { value: value, rank: numericValue };
}

// --- Helper: Rule Engine ---
function validateRules(fieldKey, value, rules, context, tierIndex = null) {
    if (value === null || value === undefined || value === "") return null;
    const settings = config[fieldKey];

    // --- 1. MENU ENFORCEMENT (The "Is it allowed?" check) ---
    if (settings.options && settings.options.length > 0) {
        const valStr = value.toString().toLowerCase();
        const isValidOption = settings.options.some(opt => opt.toLowerCase() === valStr);

        if (!isValidOption) {
            return `Sorry, "${value}" is not on our menu for ${settings.display_name}. Options: ${settings.options.join(', ')}.`;
        }
    }

    // --- 2. CONTEXTUAL RULES (The "Does it work?" checks) ---
    for (const rule of rules) {
        // Minimum Base Size Stability
        if (rule.type === 'min_base_for_tiers') {
            const currentTiers = parseInt(context.tiers || 0);
            if (currentTiers >= rule.config.tiers && tierIndex === 0) {
                const sizeRank = getOptionData(fieldKey, value).rank;
                if (sizeRank < rule.config.min_inches) return rule.error_message;
            }
        }

        // Lead Time Logic
        if (rule.type === 'lead_time') {
            const selectedDate = new Date(value);
            const minDate = new Date();
            minDate.setHours(0, 0, 0, 0); 
            minDate.setDate(minDate.getDate() + rule.config.min_days);
            if (selectedDate < minDate) return rule.error_message;
        }

        // Stacking Logic (Physics)
        if (fieldKey === 'size' && tierIndex > 0) {
            const currentSizeRank = getOptionData('size', value).rank;
            const belowTier = context.tier_definitions[tierIndex - 1];
            const sizeBelowRank = belowTier ? getOptionData('size', belowTier.size).rank : -1;

            if (sizeBelowRank !== -1 && currentSizeRank >= sizeBelowRank) {
                return `Tier ${tierIndex + 1} must be smaller than Tier ${tierIndex} (${belowTier.size}").`;
            }
        }
    }
    return null;
}

// --- 2. Process Global Fields ---
Object.keys(config).forEach(fieldKey => {
    const settings = config[fieldKey];
    if (settings.scope !== 'global') return;

    const newValue = new_ai_extraction[fieldKey];
    const valueToValidate = (newValue !== undefined && newValue !== null) ? newValue : validated_state[fieldKey];

    const depRule = settings.rules.find(r => r.type === 'dependency');
    if (depRule) {
        const parentVal = validated_state[depRule.config.depends_on];
        if (parentVal === depRule.config.value && !valueToValidate) {
            missing_items[fieldKey] = settings;
        }
    }

    const ruleError = validateRules(fieldKey, valueToValidate, settings.rules, validated_state);

    if (valueToValidate !== undefined && valueToValidate !== null) {
        validated_state[fieldKey] = valueToValidate;
        if (ruleError) error_items[fieldKey] = ruleError;
    } else if (settings.is_required !== false && !depRule) {
        missing_items[fieldKey] = settings;
    }
});

// --- 3. Sync Tier Definitions ---
const targetTierCount = parseInt(validated_state.tiers) || 0;
if (!validated_state.tier_definitions) validated_state.tier_definitions = [];

if (validated_state.tier_definitions.length !== targetTierCount) {
    if (validated_state.tier_definitions.length < targetTierCount) {
        for (let i = validated_state.tier_definitions.length; i < targetTierCount; i++) {
            validated_state.tier_definitions.push({ tier_index: i + 1, size: null, flavor: null, layers: null });
        }
    } else {
        validated_state.tier_definitions = validated_state.tier_definitions.slice(0, targetTierCount);
    }
}

// --- 4. Process Tier Scope Fields ---
validated_state.tier_definitions.forEach((tier, idx) => {
    const aiTier = (new_ai_extraction.tier_definitions || [])[idx] || {};

    Object.keys(config).forEach(fieldKey => {
        const settings = config[fieldKey];
        if (settings.scope !== 'tier') return;

        const newValue = aiTier[fieldKey];
        const valueToValidate = (newValue !== undefined && newValue !== null) ? newValue : tier[fieldKey];

        const ruleError = validateRules(fieldKey, valueToValidate, settings.rules, validated_state, idx);

        if (valueToValidate !== undefined && valueToValidate !== null) {
            tier[fieldKey] = valueToValidate;
            if (ruleError) error_items[`tier_${idx + 1}_${fieldKey}`] = ruleError;
        } else {
            missing_items[`tier_${idx + 1}_${fieldKey}`] = { 
                ...settings, 
                display_name: `Tier ${idx + 1} ${settings.display_name}` 
            };
        }
    });
});

return {
    updated_state: validated_state,
    has_errors: Object.keys(error_items).length > 0,
    errors: error_items,
    has_missing_data: Object.keys(missing_items).length > 0,
    missing: missing_items,
    is_complete: Object.keys(error_items).length === 0 && Object.keys(missing_items).length === 0
};

const order = $('save').first().json.selections

// 1. Formatting Logistics
const deliveryStatus = order.delivery === true 
    ? `🚚 *Delivery*: ${order.delivery_address || 'Address missing'}` 
    : `🏠 *Pickup*: From our Bakery`;

const acStatus = order.has_ac === true ? "✅ Required" : "❌ Not Required";

const eventDate = order.event_date 
    ? new Date(order.event_date).toLocaleDateString('en-US', { 
        weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' 
    })
    : "Date not set";

// 2. Formatting Tiers Dynamically
let layerDetails = `• *Total Layers*: ${order.layers}\n`;

if (order.layer_definitions && Array.isArray(order.layer_definitions)) {
    order.layer_definitions.forEach((layer) => {
        layerDetails += `• *Tier ${layer.layer_index}*: ${layer.size}" ${layer.flavor} cake\n`;
    });
}

// 3. Constructing the Final Message
let finalMessage = `✨ *ORDER REVIEW* ✨\n\n` +
    `Hi ${order.client_name || 'there'}! We're so excited to bake something special for you. Please review your cake details below:\n\n` +
